const _wh = $('Webhook QA').first().json || {};
const d = _wh.body || _wh;
const q = $('Tools QA').first().json || {};
const l = $('Ledger QA').first().json || {};
const reports = Array.isArray(d.reports) ? d.reports : [];
const assessments = reports.map(r => {
  let score = 1.0;
  if (r.severity === 'WARN') score -= 0.18;
  if (r.severity === 'CRIT') score -= 0.45;
  if (!r.summary || r.summary.length < 30) score -= 0.15;
  if (!Array.isArray(r.findings) || !r.findings.length) score -= 0.08;
  score = Math.max(0, Math.min(1, Math.round(score * 100) / 100));
  return {
    report_id: r.report_id || null,
    employee: r.employee || 'desconocido',
    quality_score: score,
    reason: 'Revisión Agent-QA: severidad ' + (r.severity || '?') +
      ', evidencia ' + (r.evidence ? 'presente' : 'ausente')
  };
});
const severity = (q.anomalies_count || 0) > 0 ? 'WARN' : 'OK';
const findings = [];
if ((q.probes_ok || 0) < (q.probes_total || 0)) findings.push({level:'WARN', text:(q.probes_total - q.probes_ok) + ' sondas no OK'});
if ((q.anomalies_count || 0) > 0) findings.push({level:'WARN', text:q.anomalies_count + ' anomalías recientes'});
if (!findings.length) findings.push({level:'OK', text:'Auditoría limpia y entregas completas'});
const evidence = JSON.stringify({audit:q, ledger:l}).slice(0, 4500);
const prompt = `Eres Agent-QA, auditor de calidad de HomeLab Corp. Has recibido
las entregas de los otros cuatro empleados y el resultado de una auditoría real
de Sentinel. Escribe un dictamen de 3 a 5 líneas en español sobre la calidad de
las entregas y el estado del clúster. No inventes datos y no propongas acciones
destructivas.

ENTREGAS:
${JSON.stringify(reports.map(r=>({employee:r.employee, severity:r.severity, summary:r.summary})))}

AUDITORÍA:
${evidence}

PUNTAJES ASIGNADOS:
${JSON.stringify(assessments)}
`;
return [{json: {
  employee:'Agent-QA', severity, quality_score:0.95, findings, evidence, prompt,
  assessments, directive:d.directive || '', task_id:d.task_id || null,
  round_id:d.round_id || null
}}];

const a = $('Analizar QA').first().json || {};
const l = $('LLM QA').first().json || {};
const c = (l.choices || [])[0];
const text = ((c && c.message && c.message.content) || '').trim();
return [{json: {
  employee:'Agent-QA', severity:a.severity, quality_score:a.quality_score,
  summary:(text || 'Auditoría completada').slice(0,2500), findings:a.findings || [],
  assessments:a.assessments || [], evidence:a.evidence || '',
  directive:a.directive || '', task_id:a.task_id || null, round_id:a.round_id || null
}}];

const r = $('Rendir cuentas QA').first().json || {};
const d = $('Redactar informe QA').first().json || {};
return [{json:{...d, report_id:r.report_id || null, ledger_ok:!!r.ok}}];
